 if(mode==3) {
  float a=2231.826309f, b=0.9071358749f, c=0.0928641251f;
  float s=0.1135972086f, t=-0.0180569961f;
  return x<0.0f ? x*s+t : (_exp2f(14.0f*(x-c)/b+6.0f)-64.0f)/a;
 }
 if(mode==4) return x>=171.2102947f/1023.0f ? _powf(10.0f,(x*1023.0f-420.0f)/261.5f)*0.19f-0.01f : (x*1023.0f-95.0f)*0.01125f/(171.2102947f-95.0f);
 if(mode==5) return x<0.0f ? x/15.1927f-0.01f : (_powf(10.0f,x/0.224282f)-1.0f)/155.975327f-0.01f;
 if(mode==6) return x<0.181f ? (x-0.125f)/5.6f : _powf(10.0f,(x-0.598206f)/0.241514f)-0.00873f;
 if(mode==7) return x<0.1338837831f ? (x-0.0924657534f)/8.2836059324f : _expf((x-0.5300133392f)/0.0869287607f)-0.0054940724f;
